#!/usr/bin/env bash
# Populate assets/fonts with the exact font binaries used by the project.
# The binaries are third-party assets, not generated by us, so they are kept
# out of Git; the license texts stay in the repository.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DST="$ROOT/assets/fonts"
mkdir -p "$DST"

copy_checked() {
  local src="$1" name="$2" expected="$3"
  local dst="$DST/$name"
  if [ -f "$dst" ]; then
    local actual
    actual="$(sha256sum "$dst" | awk '{print $1}')"
    if [ "$actual" = "$expected" ]; then
      echo "ok   $name"
      return 0
    fi
    echo "FAIL $name exists but hash differs" >&2
    return 1
  fi
  if [ ! -f "$src" ]; then
    echo "MISS $name; expected source: $src" >&2
    return 1
  fi
  cp "$src" "$dst"
  local actual
  actual="$(sha256sum "$dst" | awk '{print $1}')"
  if [ "$actual" != "$expected" ]; then
    echo "FAIL $name hash mismatch" >&2
    return 1
  fi
  echo "copy $name"
}

copy_checked "/usr/share/fonts/adobe-source-han-sans/SourceHanSansCN-Regular.otf" \
  "SourceHanSansCN-Regular.otf" "e2bc8a2e7f37474b774fff8db758681ece40bb6947a90d571bce9dd60671a8e4"
copy_checked "/usr/share/fonts/adobe-source-han-sans/SourceHanSansCN-Bold.otf" \
  "SourceHanSansCN-Bold.otf" "62383707c086a32f3afd5e293f34c7eff64c7fea31f579fdc6cbe34d920519a6"
copy_checked "/usr/share/fonts/adobe-source-han-serif/SourceHanSerifCN-Regular.otf" \
  "SourceHanSerifCN-Regular.otf" "3754ea669c530e2473354f8f6d9f79680a44d7e26ec7d00eeabee4a7e0753c5d"
copy_checked "/usr/share/fonts/adobe-source-han-serif/SourceHanSerifCN-SemiBold.otf" \
  "SourceHanSerifCN-SemiBold.otf" "50d3f12201ce2dd840650b6bfa47ebb8572ecf767eec0e5ccb20a247b5bfa805"
copy_checked "/usr/share/fonts/lxgw-wenkai-v1.522/LXGWWenKai-Regular.ttf" \
  "LXGWWenKai-Regular.ttf" "39ad71264b588165b469e35e6afb162a378dacd1f95348160240ba9038ac3009"

echo "fonts ready in $DST"
